795	+/// `lazySingleton` (Code Map), like `AccountSettingsCubit` — long-lived, so
796	+/// the already-fetched pages survive leaving and re-entering
797	+/// `/meus-registros` within the same app session.
798	+class MeusRegistrosCubit extends Cubit<MeusRegistrosState> {
799	+  MeusRegistrosCubit(this._repository) : super(const MeusRegistrosLoading());
800	+
801	+  final EntriesRepository _repository;
802	+
803	+  /// A monotonic counter guarding against a stale in-flight call's result
804	+  /// landing after a newer call has already changed the state (e.g. the
805	+  /// user leaves and quickly re-enters `/meus-registros` while a slow
806	+  /// first request is still pending, or taps retry before the original
807	+  /// request resolves). Incremented at the start of every [loadFirstPage],
808	+  /// then captured locally before each `await` in [loadFirstPage]/
809	+  /// [_fetchMore] — a result whose captured generation no longer matches
810	+  /// this counter by the time it resolves is discarded rather than
811	+  /// emitted.
812	+  int _generation = 0;
813	+
814	+  /// `MeusRegistrosScreen.initState` calls this once, every mount — always
815	+  /// re-fetches from scratch rather than keeping a previous visit's page
816	+  /// around, since a new entry may have been saved (Insertion Modal, Epic
817	+  /// 3) since the last visit.
818	+  Future<void> loadFirstPage() async {
819	+    final generation = ++_generation;
820	+    emit(const MeusRegistrosLoading());
821	+    final result = await _repository.list();
822	+    // Mirrors `AccountSettingsCubit.toggleBiometric`'s own guard: `close()`
823	+    // can race this awaited call (e.g. a fast app teardown mid-request) —
824	+    // `emit()` after `close()` would otherwise throw.
825	+    if (isClosed || generation != _generation) {
826	+      return;
827	+    }
828	+    result.match(
829	+      (failure) => emit(MeusRegistrosError(message: failure.message)),
830	+      (page) {
831	+        if (page.items.isEmpty) {
832	+          emit(const MeusRegistrosEmpty());
833	+          return;
834	+        }
835	+        emit(
836	+          MeusRegistrosLoaded(entries: page.items, nextCursor: page.nextCursor),
837	+        );
838	+      },
839	+    );
840	+  }
841	+
842	+  /// `MeusRegistrosScreen`'s scroll listener calls this near the list's
843	+  /// end. A no-op while not [MeusRegistrosLoaded], while
844	+  /// [MeusRegistrosLoaded.nextCursor] is already `null`, while a call is
845	+  /// already in flight, or — critically — once
846	+  /// [MeusRegistrosLoaded.loadMoreFailed] is already `true`: without that
847	+  /// last guard, a failed page's own footer swapping from a spinner to a
848	+  /// "Tentar novamente" button can shift the list's `maxScrollExtent`
849	+  /// just enough to leave the scroll position still inside the
850	+  /// pre-fetch-buffer zone, re-firing this same listener and retrying
851	+  /// forever — observed directly as an unbounded `pumpAndSettle` loop in
852	+  /// this screen's own widget test. Once failed, only an explicit
853	+  /// [retryLoadMore] (the footer's own button) tries again.
854	+  Future<void> loadMore() => _fetchMore(isRetry: false);
855	+
856	+  /// The footer's "Tentar novamente" button — the one path allowed to
857	+  /// retry past a [MeusRegistrosLoaded.loadMoreFailed] of `true`
858	+  /// ([loadMore]'s own doc).
859	+  Future<void> retryLoadMore() => _fetchMore(isRetry: true);
860	+
861	+  Future<void> _fetchMore({required bool isRetry}) async {
862	+    final current = state;
863	+    if (current is! MeusRegistrosLoaded ||
864	+        current.nextCursor == null ||
865	+        current.isLoadingMore ||
866	+        (current.loadMoreFailed && !isRetry)) {
867	+      return;
868	+    }
869	+    final generation = _generation;
870	+    emit(current.copyWith(isLoadingMore: true, loadMoreFailed: false));
871	+    final result = await _repository.list(cursor: current.nextCursor);
872	+    if (isClosed || generation != _generation) {
873	+      return;
874	+    }
875	+    // Re-reads `state` rather than closing over `current` — defensive
876	+    // against `loadFirstPage()` having reset the state to something other
877	+    // than `MeusRegistrosLoaded` while this await was pending.
878	+    final latest = state;
879	+    if (latest is! MeusRegistrosLoaded) {
880	+      return;
881	+    }
882	+    result.match(
883	+      (failure) =>
884	+          emit(latest.copyWith(isLoadingMore: false, loadMoreFailed: true)),
885	+      (page) {
886	+        // I/O matrix: "Next page appended, no dup ids" — defensive
887	+        // de-duplication in case a cursor-boundary entry is ever repeated
888	+        // by the server.
889	+        final existingIds = latest.entries.map((entry) => entry.id).toSet();
890	+        final newEntries = page.items
891	+            .where((entry) => !existingIds.contains(entry.id))
892	+            .toList();
893	+        // Defensive guard against a degenerate server response: if every
894	+        // item in this "successful" page was already present by id (zero
895	+        // genuinely-new entries) yet the server still reports a non-null
896	+        // `nextCursor`, treat the page as exhausted rather than trusting
897	+        // that cursor — otherwise a misbehaving/stuck server cursor could
898	+        // make the scroll listener keep re-triggering `loadMore()`
899	+        // indefinitely with no progress.
900	+        final nextCursor = newEntries.isEmpty ? null : page.nextCursor;
901	+        emit(
902	+          MeusRegistrosLoaded(
903	+            entries: [...latest.entries, ...newEntries],
904	+            nextCursor: nextCursor,
905	+          ),
906	+        );
907	+      },
908	+    );
909	+  }
910	+}
