1350	+/// "Hoje"/"Ontem"/`dd/mm/yyyy` — presentation's own job (Code Map: day
1351	+/// labels aren't the pure `groupEntriesByDate()`'s concern). [date] is
1352	+/// always already truncated to local midnight (`EntryDateGroup`'s own
1353	+/// contract).
1354	+String _dayLabel(DateTime date) {
1355	+  final now = DateTime.now();
1356	+  final today = DateTime(now.year, now.month, now.day);
1357	+  final yesterday = today.subtract(const Duration(days: 1));
1358	+  if (date == today) {
1359	+    return 'Hoje';
1360	+  }
1361	+  if (date == yesterday) {
1362	+    return 'Ontem';
1363	+  }
1364	+  final day = date.day.toString().padLeft(2, '0');
1365	+  final month = date.month.toString().padLeft(2, '0');
1366	+  return '$day/$month/${date.year}';
1367	+}
