3679	+/// call unresolved to observe the skeleton's 300ms threshold.
3680	+class _FakeEntriesRepository implements EntriesRepository {
3681	+  final List<Either<Failure, EntriesPage>> _listResults = [];
3682	+  int listCallCount = 0;
3683	+  Completer<void>? firstCallGate;
3684	+
3685	+  void queueList(Either<Failure, EntriesPage> result) {
3686	+    _listResults.add(result);
3687	+  }
3688	+
3689	+  @override
3690	+  Future<Either<Failure, Entry>> create({
3691	+    required String content,
3692	+    required EntrySource source,
3693	+    int? mediaDurationSeconds,
3694	+  }) async => throw UnimplementedError('not expected to be called');
3695	+
3696	+  @override
3697	+  Future<Either<Failure, EntriesPage>> list({
3698	+    String? cursor,
3699	+    int limit = 20,
3700	+  }) async {
3701	+    listCallCount++;
3702	+    if (listCallCount == 1 && firstCallGate != null) {
3703	+      await firstCallGate!.future;
3704	+    }
3705	+    if (_listResults.isEmpty) {
3706	+      throw StateError('no queued list() result for call #$listCallCount');
3707	+    }
3708	+    return _listResults.removeAt(0);
3709	+  }
